sys_script_include.script:
var ProjectMCPStoryServiceSNC = Class.create();

ProjectMCPStoryServiceSNC.prototype = {

    initialize: function() {},


    /********************************************************************
     * GET STORY DETAILS
     ********************************************************************/

    getByNumber: function(number) {
        if (gs.nil(number)) {
            return {
                success: false,
                status: 400,
                error: 'Missing required parameter: number'
            };
        }

        var story = new GlideRecordSecure('rm_story');
        story.addQuery('number', number);
        story.setLimit(1);
        story.query();

        if (!story.next()) {
            return {
                success: false,
                status: 404,
                error: 'Story not found: ' + number
            };
        }

        var data = this._serializeStoryDetails(story);

        data.activity = {
            comments: this._journalEntries(story, 'comments'),
            work_notes: this._journalEntries(story, 'work_notes')
        };

        data.attachments = this._getAttachments(
            story.getUniqueValue()
        );

        return {
            success: true,
            status: 200,
            data: data
        };
    },


    /********************************************************************
     * LIST STORIES FOR PROJECT
     ********************************************************************/

    listForProject: function(projectNumber, options) {
        if (gs.nil(projectNumber)) {
            return {
                success: false,
                status: 400,
                error: 'Missing required parameter: project number'
            };
        }

        options = options || {};

        var limit = this._parseInteger(
            options.limit,
            50,
            1,
            100
        );

        var offset = this._parseInteger(
            options.offset,
            0,
            0,
            100000
        );

        var project = new GlideRecordSecure('pm_project');
        project.addQuery('number', projectNumber);
        project.setLimit(1);
        project.query();

        if (!project.next()) {
            return {
                success: false,
                status: 404,
                error: 'Project not found: ' + projectNumber
            };
        }

        var stories = [];

        var story = new GlideRecordSecure('rm_story');

        story.addQuery(
            'project',
            project.getUniqueValue()
        );

        story.orderBy('priority');
        story.orderBy('number');

        story.chooseWindow(
            offset,
            offset + limit + 1
        );

        story.query();

        while (story.next()) {
            stories.push(
                this._serializeStory(story)
            );

            if (stories.length > limit) {
                break;
            }
        }

        var hasMore = stories.length > limit;

        if (hasMore) {
            stories.pop();
        }

        return {
            success: true,
            status: 200,
            data: {
                project: {
                    sys_id: project.getUniqueValue(),
                    number: this._value(
                        project,
                        'number'
                    ),
                    short_description: this._value(
                        project,
                        'short_description'
                    )
                },

                stories: stories,

                pagination: {
                    limit: limit,
                    offset: offset,
                    returned: stories.length,
                    has_more: hasMore,
                    next_offset: hasMore
                        ? offset + limit
                        : null
                }
            }
        };
    },


    /********************************************************************
     * CREATE STORY
     ********************************************************************/

    createStory: function(input) {
        if (!input || typeof input !== 'object') {
            return {
                success: false,
                status: 400,
                error: 'Request body is required'
            };
        }

        if (!this._has(input, 'short_description')) {
            return {
                success: false,
                status: 400,
                error: 'short_description is required'
            };
        }

        var story = new GlideRecordSecure('rm_story');
        story.initialize();

        if (!story.canCreate()) {
            return {
                success: false,
                status: 403,
                error: 'Not authorized to create stories'
            };
        }

        var result;

        /*
         * Required field
         */
        result = this._setNonEmptyField(
            story,
            'short_description',
            input.short_description
        );

        if (!result.success) {
            return result;
        }


        /*
         * Optional string / choice fields
         */
        if (this._has(input, 'description')) {
            result = this._setSimpleField(
                story,
                'description',
                input.description
            );

            if (!result.success) {
                return result;
            }
        }

        if (this._has(input, 'acceptance_criteria')) {
            result = this._setSimpleField(
                story,
                'acceptance_criteria',
                input.acceptance_criteria
            );

            if (!result.success) {
                return result;
            }
        }

        if (this._has(input, 'priority')) {
            result = this._setNonEmptyField(
                story,
                'priority',
                input.priority
            );

            if (!result.success) {
                return result;
            }
        }


        /*
         * Story points
         */
        if (this._has(input, 'story_points')) {
            result = this._setStoryPoints(
                story,
                input.story_points
            );

            if (!result.success) {
                return result;
            }
        }


        /*
         * Reference fields
         */
        var referenceFields = [
            'project',
            'sprint',
            'assigned_to',
            'assignment_group'
        ];

        for (var i = 0; i < referenceFields.length; i++) {
            var fieldName = referenceFields[i];

            if (!this._has(input, fieldName)) {
                continue;
            }

            result = this._setReferenceField(
                story,
                fieldName,
                input[fieldName]
            );

            if (!result.success) {
                return result;
            }
        }


        var sysId = story.insert();

        if (gs.nil(sysId)) {
            return {
                success: false,
                status: 500,
                error: 'Failed to create story'
            };
        }


        /*
         * Re-query so returned values reflect business rules,
         * defaults, display values, etc.
         */
        var createdStory =
            new GlideRecordSecure('rm_story');

        if (!createdStory.get(sysId)) {
            return {
                success: false,
                status: 500,
                error: 'Story was created but could not be retrieved'
            };
        }

        return {
            success: true,
            status: 201,
            data: this._serializeStoryDetails(
                createdStory
            )
        };
    },


    /********************************************************************
     * MODIFY STORY
     ********************************************************************/

    modifyStory: function(number, input) {
        if (gs.nil(number)) {
            return {
                success: false,
                status: 400,
                error: 'Missing required parameter: number'
            };
        }

        if (!input || typeof input !== 'object') {
            return {
                success: false,
                status: 400,
                error: 'Request body is required'
            };
        }

        var story = new GlideRecordSecure('rm_story');
        story.addQuery('number', number);
        story.setLimit(1);
        story.query();

        if (!story.next()) {
            return {
                success: false,
                status: 404,
                error: 'Story not found: ' + number
            };
        }

        if (!story.canWrite()) {
            return {
                success: false,
                status: 403,
                error: 'Not authorized to modify story: ' + number
            };
        }

        var updatedFields = [];
        var result;


        /*
         * Normal fields.
         *
         * Blank/null values are ignored. They DO NOT clear fields.
         */
        if (this._has(input, 'short_description')) {
            result = this._setNonEmptyField(
                story,
                'short_description',
                input.short_description
            );

            if (!result.success) {
                return result;
            }

            updatedFields.push('short_description');
        }

        if (this._has(input, 'description')) {
            result = this._setSimpleField(
                story,
                'description',
                input.description
            );

            if (!result.success) {
                return result;
            }

            updatedFields.push('description');
        }

        if (this._has(input, 'acceptance_criteria')) {
            result = this._setSimpleField(
                story,
                'acceptance_criteria',
                input.acceptance_criteria
            );

            if (!result.success) {
                return result;
            }

            updatedFields.push('acceptance_criteria');
        }

        if (this._has(input, 'state')) {
            result = this._setNonEmptyField(
                story,
                'state',
                input.state
            );

            if (!result.success) {
                return result;
            }

            updatedFields.push('state');
        }

        if (this._has(input, 'priority')) {
            result = this._setNonEmptyField(
                story,
                'priority',
                input.priority
            );

            if (!result.success) {
                return result;
            }

            updatedFields.push('priority');
        }

        if (this._has(input, 'story_points')) {
            result = this._setStoryPoints(
                story,
                input.story_points
            );

            if (!result.success) {
                return result;
            }

            updatedFields.push('story_points');
        }

        if (this._has(input, 'blocked')) {
            result = this._setBooleanField(
                story,
                'blocked',
                input.blocked
            );

            if (!result.success) {
                return result;
            }

            updatedFields.push('blocked');
        }


        /*
         * Non-clearable reference fields.
         *
         * Blank/null means "leave unchanged."
         */
        var referenceFields = [
            'project',
            'sprint'
        ];

        for (var ri = 0; ri < referenceFields.length; ri++) {
            var refField = referenceFields[ri];

            if (!this._has(input, refField)) {
                continue;
            }

            result = this._setReferenceField(
                story,
                refField,
                input[refField]
            );

            if (!result.success) {
                return result;
            }

            updatedFields.push(refField);
        }


        /*
         * Clearable reference fields.
         *
         * These are intentionally the ONLY fields where supplying
         * null or an empty string clears the existing value.
         */
        var clearableFields = [
            'assigned_to',
            'assignment_group'
        ];

        for (var ci = 0; ci < clearableFields.length; ci++) {
            var clearField = clearableFields[ci];

            /*
             * IMPORTANT:
             * Use the Rhino-safe `in` operator here.
             *
             * Do NOT use:
             * Object.prototype.hasOwnProperty.call(...)
             *
             * request.body.data is a Rhino NativeObject and the
             * hasOwnProperty.call pattern can trigger the
             * NativeObject/BaseFunction exception.
             */
            if (!(clearField in input)) {
                continue;
            }

            var clearValue = input[clearField];

            var shouldClear =
                clearValue === null ||
                typeof clearValue === 'undefined' ||
                (
                    typeof clearValue === 'string' &&
                    clearValue.replace(
                        /^\s+|\s+$/g,
                        ''
                    ) === ''
                );

            if (shouldClear) {
                if (!story.isValidField(clearField)) {
                    return {
                        success: false,
                        status: 400,
                        error: 'Invalid field: ' + clearField
                    };
                }

                var clearElement =
                    story.getElement(clearField);

                if (
                    clearElement &&
                    !clearElement.canWrite()
                ) {
                    return {
                        success: false,
                        status: 403,
                        error:
                            'Not authorized to modify field: ' +
                            clearField
                    };
                }

                story.setValue(clearField, '');
            } else {
                result = this._setReferenceField(
                    story,
                    clearField,
                    clearValue
                );

                if (!result.success) {
                    return result;
                }
            }

            updatedFields.push(clearField);
        }


        /*
         * Journal fields.
         *
         * Journal fields must be assigned directly rather than
         * using setValue().
         */
        if (this._has(input, 'work_notes')) {
            story.work_notes =
                String(input.work_notes);

            updatedFields.push('work_notes');
        }

        if (this._has(input, 'comments')) {
            story.comments =
                String(input.comments);

            updatedFields.push('comments');
        }


        if (updatedFields.length === 0) {
            return {
                success: false,
                status: 400,
                error: 'No modifiable fields provided'
            };
        }


        var updatedSysId = story.update();

        if (gs.nil(updatedSysId)) {
            return {
                success: false,
                status: 500,
                error: 'Failed to update story'
            };
        }


        /*
         * Reload the record so returned values reflect business
         * rules or other changes made during update.
         */
        var updatedStory =
            new GlideRecordSecure('rm_story');

        if (!updatedStory.get(updatedSysId)) {
            return {
                success: false,
                status: 500,
                error: 'Story was updated but could not be retrieved'
            };
        }

        return {
            success: true,
            status: 200,
            data: {
                status: 'updated',
                updated_fields: updatedFields,
                story: this._serializeStoryDetails(
                    updatedStory
                )
            }
        };
    },


    /********************************************************************
     * SERIALIZATION
     ********************************************************************/

    _serializeStoryDetails: function(story) {
        return {
            sys_id: story.getUniqueValue(),

            number: this._value(
                story,
                'number'
            ),

            short_description: this._value(
                story,
                'short_description'
            ),

            description: this._value(
                story,
                'description'
            ),

            acceptance_criteria: this._value(
                story,
                'acceptance_criteria'
            ),

            state: this._valueAndDisplay(
                story,
                'state'
            ),

            priority: this._valueAndDisplay(
                story,
                'priority'
            ),

            type: this._valueAndDisplay(
                story,
                'type'
            ),

            classification: this._valueAndDisplay(
                story,
                'classification'
            ),

            points: this._number(
                story,
                'story_points'
            ),

            blocked: this._boolean(
                story,
                'blocked'
            ),

            active: this._boolean(
                story,
                'active'
            ),

            project: this._reference(
                story,
                'project'
            ),

            project_phase: this._reference(
                story,
                'project_phase'
            ),

            assignment_group: this._reference(
                story,
                'assignment_group'
            ),

            assigned_to: this._reference(
                story,
                'assigned_to'
            ),

            sprint: this._reference(
                story,
                'sprint'
            ),

            epic: this._reference(
                story,
                'epic'
            ),

            product: this._reference(
                story,
                'product'
            ),

            release: this._reference(
                story,
                'release'
            ),

            theme: this._reference(
                story,
                'theme'
            ),

            demand: this._reference(
                story,
                'demand'
            ),

            sys_created_on: this._value(
                story,
                'sys_created_on'
            ),

            sys_updated_on: this._value(
                story,
                'sys_updated_on'
            )
        };
    },


    _serializeStory: function(story) {
        return {
            sys_id: story.getUniqueValue(),

            number: this._value(
                story,
                'number'
            ),

            short_description: this._value(
                story,
                'short_description'
            ),

            state: this._valueAndDisplay(
                story,
                'state'
            ),

            priority: this._valueAndDisplay(
                story,
                'priority'
            ),

            points: this._number(
                story,
                'story_points'
            ),

            blocked: this._boolean(
                story,
                'blocked'
            ),

            active: this._boolean(
                story,
                'active'
            ),

            project: this._reference(
                story,
                'project'
            ),

            assignment_group: this._reference(
                story,
                'assignment_group'
            ),

            assigned_to: this._reference(
                story,
                'assigned_to'
            ),

            sprint: this._reference(
                story,
                'sprint'
            ),

            sys_updated_on: this._value(
                story,
                'sys_updated_on'
            )
        };
    },


    /********************************************************************
     * ATTACHMENTS
     ********************************************************************/

    _getAttachments: function(storySysId) {
        var attachments = [];

        var attachment =
            new GlideRecordSecure('sys_attachment');

        attachment.addQuery(
            'table_name',
            'rm_story'
        );

        attachment.addQuery(
            'table_sys_id',
            storySysId
        );

        attachment.orderBy('sys_created_on');
        attachment.query();

        var maxSizeBytes =
            5 * 1024 * 1024;

        while (attachment.next()) {
            var sizeBytes = parseInt(
                attachment.getValue('size_bytes'),
                10
            );

            if (isNaN(sizeBytes)) {
                sizeBytes = 0;
            }

            attachments.push({
                sys_id: attachment.getUniqueValue(),

                file_name: attachment.getValue(
                    'file_name'
                ),

                download_allowed:
                    sizeBytes <= maxSizeBytes,

                created_on: attachment.getValue(
                    'sys_created_on'
                ),

                created_by: attachment.getValue(
                    'sys_created_by'
                )
            });
        }

        return attachments;
    },


    /********************************************************************
     * MODIFY / CREATE HELPERS
     ********************************************************************/

    _setSimpleField: function(
        gr,
        fieldName,
        value
    ) {
        if (!gr.isValidField(fieldName)) {
            return {
                success: false,
                status: 400,
                error: 'Invalid field: ' + fieldName
            };
        }

        var element = gr.getElement(fieldName);

        if (element && !element.canWrite()) {
            return {
                success: false,
                status: 403,
                error:
                    'Not authorized to modify field: ' +
                    fieldName
            };
        }

        gr.setValue(
            fieldName,
            String(value)
        );

        return {
            success: true
        };
    },


    _setNonEmptyField: function(
        gr,
        fieldName,
        value
    ) {
        if (
            value === null ||
            typeof value === 'undefined'
        ) {
            return {
                success: false,
                status: 400,
                error:
                    fieldName +
                    ' cannot be empty'
            };
        }

        var stringValue =
            String(value).replace(
                /^\s+|\s+$/g,
                ''
            );

        if (stringValue === '') {
            return {
                success: false,
                status: 400,
                error:
                    fieldName +
                    ' cannot be empty'
            };
        }

        return this._setSimpleField(
            gr,
            fieldName,
            value
        );
    },


    _setStoryPoints: function(
        gr,
        value
    ) {
        var points =
            parseFloat(value);

        if (
            isNaN(points) ||
            points < 0
        ) {
            return {
                success: false,
                status: 400,
                error:
                    'story_points must be a non-negative number'
            };
        }

        return this._setSimpleField(
            gr,
            'story_points',
            points
        );
    },


    _setBooleanField: function(
        gr,
        fieldName,
        value
    ) {
        var boolValue;

        if (value === true) {
            boolValue = true;
        } else if (value === false) {
            boolValue = false;
        } else {
            var stringValue =
                String(value).toLowerCase();

            if (
                stringValue === 'true' ||
                stringValue === '1'
            ) {
                boolValue = true;
            } else if (
                stringValue === 'false' ||
                stringValue === '0'
            ) {
                boolValue = false;
            } else {
                return {
                    success: false,
                    status: 400,
                    error:
                        fieldName +
                        ' must be true or false'
                };
            }
        }

        return this._setSimpleField(
            gr,
            fieldName,
            boolValue ? 'true' : 'false'
        );
    },


    _setReferenceField: function(
        gr,
        fieldName,
        value
    ) {
        if (!gr.isValidField(fieldName)) {
            return {
                success: false,
                status: 400,
                error: 'Invalid field: ' + fieldName
            };
        }

        var element =
            gr.getElement(fieldName);

        if (element && !element.canWrite()) {
            return {
                success: false,
                status: 403,
                error:
                    'Not authorized to modify field: ' +
                    fieldName
            };
        }

        if (
            value === null ||
            typeof value === 'undefined'
        ) {
            return {
                success: false,
                status: 400,
                error:
                    fieldName +
                    ' cannot be empty'
            };
        }

        value = String(value).replace(
            /^\s+|\s+$/g,
            ''
        );

        if (value === '') {
            return {
                success: false,
                status: 400,
                error:
                    fieldName +
                    ' cannot be empty'
            };
        }


        /*
         * Explicit reference configuration for the reference
         * fields currently supported by Create/Modify Story.
         */
        var config = null;

        if (fieldName === 'project') {
            config = {
                table: 'pm_project',
                lookup_fields: [
                    'number',
                    'name'
                ]
            };
        } else if (fieldName === 'sprint') {
            config = {
                table: 'sn_cwm_sprint',
                lookup_fields: [
                    'number',
                    'name'
                ]
            };
        } else if (fieldName === 'assigned_to') {
            config = {
                table: 'sys_user',
                lookup_fields: [
                    'user_name',
                    'name'
                ]
            };
        } else if (fieldName === 'assignment_group') {
            config = {
                table: 'sys_user_group',
                lookup_fields: [
                    'name'
                ]
            };
        } else {
            return {
                success: false,
                status: 400,
                error:
                    'Unsupported reference field: ' +
                    fieldName
            };
        }


        /*
         * First try the supplied value as a sys_id.
         */
        var reference =
            new GlideRecordSecure(config.table);

        reference.addQuery(
            'sys_id',
            value
        );

        reference.setLimit(1);
        reference.query();

        if (reference.next()) {
            gr.setValue(
                fieldName,
                reference.getUniqueValue()
            );

            return {
                success: true
            };
        }


        /*
         * Otherwise resolve against the supported human-readable
         * identifiers for that table.
         */
        reference =
            new GlideRecordSecure(config.table);

        var queryCondition = null;

        for (
            var i = 0;
            i < config.lookup_fields.length;
            i++
        ) {
            var lookupField =
                config.lookup_fields[i];

            if (!reference.isValidField(lookupField)) {
                continue;
            }

            if (queryCondition === null) {
                queryCondition =
                    reference.addQuery(
                        lookupField,
                        value
                    );
            } else {
                queryCondition.addOrCondition(
                    lookupField,
                    value
                );
            }
        }

        if (queryCondition === null) {
            return {
                success: false,
                status: 500,
                error:
                    'No valid lookup fields available for ' +
                    fieldName
            };
        }

        reference.setLimit(2);
        reference.query();

        if (!reference.next()) {
            return {
                success: false,
                status: 404,
                error:
                    'No matching ' +
                    fieldName +
                    ' found: ' +
                    value
            };
        }

        var resolvedSysId =
            reference.getUniqueValue();

        /*
         * More than one exact match is ambiguous.
         * Require the caller to supply sys_id instead.
         */
        if (reference.next()) {
            return {
                success: false,
                status: 409,
                error:
                    'Multiple matching values found for ' +
                    fieldName +
                    ': ' +
                    value +
                    '. Use sys_id instead.'
            };
        }

        gr.setValue(
            fieldName,
            resolvedSysId
        );

        return {
            success: true
        };
    },


    /*
     * Returns true only when the property exists AND contains
     * a meaningful value.
     *
     * false and 0 are intentionally considered valid values.
     *
     * Uses the Rhino-safe `in` operator rather than
     * Object.prototype.hasOwnProperty.call().
     */
    _has: function(
        input,
        fieldName
    ) {
        if (!input) {
            return false;
        }

        if (!(fieldName in input)) {
            return false;
        }

        var value =
            input[fieldName];

        if (
            value === null ||
            typeof value === 'undefined'
        ) {
            return false;
        }

        if (
            typeof value === 'string' &&
            value.replace(
                /^\s+|\s+$/g,
                ''
            ) === ''
        ) {
            return false;
        }

        return true;
    },


    /********************************************************************
     * READ HELPERS
     ********************************************************************/

    _value: function(
        gr,
        fieldName
    ) {
        if (!gr.isValidField(fieldName)) {
            return null;
        }

        var value =
            gr.getValue(fieldName);

        return gs.nil(value)
            ? null
            : value;
    },


    _valueAndDisplay: function(
        gr,
        fieldName
    ) {
        if (!gr.isValidField(fieldName)) {
            return null;
        }

        var value =
            gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return {
            value: value,
            display_value:
                gr.getDisplayValue(fieldName)
        };
    },


    _reference: function(
        gr,
        fieldName
    ) {
        if (!gr.isValidField(fieldName)) {
            return null;
        }

        var value =
            gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return {
            value: value,
            display_value:
                gr.getDisplayValue(fieldName)
        };
    },


    _number: function(
        gr,
        fieldName
    ) {
        if (!gr.isValidField(fieldName)) {
            return null;
        }

        var value =
            gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        var number =
            parseFloat(value);

        return isNaN(number)
            ? null
            : number;
    },


    _boolean: function(
        gr,
        fieldName
    ) {
        if (!gr.isValidField(fieldName)) {
            return null;
        }

        var value =
            gr.getValue(fieldName);

        if (gs.nil(value)) {
            return null;
        }

        return (
            value === 'true' ||
            value === '1'
        );
    },


    _journalEntries: function(
        gr,
        fieldName
    ) {
        if (!gr.isValidField(fieldName)) {
            return null;
        }

        try {
            /*
             * -1 returns the complete journal history rather than
             * only the most recent entry.
             */
            return gr[fieldName]
                .getJournalEntry(-1);
        } catch (e) {
            return null;
        }
    },


    _parseInteger: function(
        value,
        defaultValue,
        min,
        max
    ) {
        var parsed =
            parseInt(value, 10);

        if (isNaN(parsed)) {
            parsed = defaultValue;
        }

        if (parsed < min) {
            parsed = min;
        }

        if (parsed > max) {
            parsed = max;
        }

        return parsed;
    },


    type: 'ProjectMCPStoryServiceSNC'
};
